INSERT INTO public.ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources, owner_seat) VALUES (489, $t$1$t$, $t$Twin anon policies dropped on debate_candidate_findings and tier3_verdicts$t$, $t$Each table keeps one policy per role and command, so a later change (such as closing an anon write) cannot be undone by a forgotten twin. Expected effect: what each role can read and write is the same before and after. (ask489/plan489.md)$t$, $t$yes$t$, $t$Written (audit 38718) and read back by W1 (9806) and W3 (9809): one policy per role and command, and the same effective access before and after.$t$, $t$9806, 9809$t$, 'session_01H1X3APzb2DidJoZ9Avizjn', NULL, $j$"not yet"$j$::jsonb, $j${"thread": "W4", "press_time": "18:05:09Z", "answer": "Write it", "source": "audit 38718"}$j$::jsonb, $j${"path": "ask489/plan489.md", "md5": "2f3c271b", "commit": "not yet", "wall_id": 9687}$j$::jsonb, $j$[{"path": "ask489/step489.sql", "md5": "0fd91b1c", "commit": "not yet"}]$j$::jsonb, $j${"path": "ask489/revert489.sql", "md5": "33c09658"}$j$::jsonb, $j$[{"seat": "W3", "verdict": "PASS (rev 0; step 6b24a3a7)", "verdict_norm": "PASS", "md5_graded": "6b24a3a7", "wall_id": 9688}, {"seat": "W1", "verdict": "PASS with N1", "verdict_norm": "PASS", "md5_graded": "0fd91b1c", "wall_id": 9695}, {"seat": "W1", "verdict": "PASS with N1", "verdict_norm": "PASS", "md5_graded": "2f3c271b", "wall_id": 9695}]$j$::jsonb, ARRAY['0fd91b1c']::text[], $j$[38718]$j$::jsonb, $j$[{"kind": "policy", "name": "anon_ins, anon_sel on debate_candidate_findings and tier3_verdicts", "before": "present", "after": "dropped"}]$j$::jsonb, $j$[{"file": "ask489/test489_rollback.sql", "md5": "06ddffca", "result": "every line PASS", "wall_id": 9720}]$j$::jsonb, $j$[{"seat": "W1", "result": "CONFIRMED", "wall_id": 980