INSERT INTO public.ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources, owner_seat) VALUES (491, $t$3$t$, $t$Anon EXECUTE revoked on dash_launch_debate, debate_queue_expire_stale, pick_next_debate$t$, $t$A holder of the public (anon) key cannot launch a W1 debate without the dashboard passphrase, cannot mark queued jobs failed, and cannot claim the next queued job. The dashboard launch (through dash_api, with the passphrase), the hourly expiry job and the engine are unchanged. (ask491/plan491.md)$t$, $t$in part$t$, $t$Written (audit 38745) and read back by W1 (9820) and W3 (9824): anon is refused. The hourly expiry job ran after the write and succeeded (W1 9836). A dashboard launch and an engine claim since the write are not yet shown.$t$, $t$9820, 9824, 9836$t$, 'session_01H1X3APzb2DidJoZ9Avizjn', NULL, $j$"not yet"$j$::jsonb, $j${"thread": "W4", "press_time": "18:11:13Z", "answer": "Write it", "source": "audit 38745"}$j$::jsonb, $j${"path": "a491_w2/plan491.md", "md5": "513e4f7d", "commit": "9f2f486a", "wall_id": 9781}$j$::jsonb, $j$[{"path": "a491_w2/step491.sql", "md5": "7074eb34", "commit": "9f2f486a"}]$j$::jsonb, $j${"path": "a491_w2/revert491.sql", "md5": "6841b272"}$j$::jsonb, $j$[{"seat": "W1", "verdict": "PASS", "verdict_norm": "PASS", "md5_graded": "7074eb34", "wall_id": 9735}, {"seat": "W3", "verdict": "PASS", "verdict_norm": "PASS", "md5_graded": "7074eb34", "wall_id": 9737}, {"seat": "W1", "verdict": "PASS on form", "verdict_norm": "PASS", "md5_graded": "513e4f7d", "wall_id": 9782}, {"seat": "W3", "verdict": "PASS ON FORM", "verdict_norm": "PASS", "md5_graded": "513e4f7d", "wall_id": 9783}]$j$::jsonb, ARRAY['7074eb34']::text[], $j$[38745]$j$::jsonb, $j$[{"kind": "function grants", "name": "dash_launch_debate, debate_queue_expire_stale, pick_next_debate", "before": "EXECUTE to PUBLIC, anon, authenticated", "after": "revoked"}]$j$::jsonb, $j$[{"file": "a491_w2/test491_rollback.sql", "md5": "a853825b", "result": "all PASS", "wall_id": 9751}]$j$::jsonb, $j$[{"seat": "W1", "result": "CONFIRMED", "wall_id": 9820}, {"seat": "W3", "result": "CONFIRMED", "wall_id": 9824}]$j$::jsonb, $j${"case": "debate-queue-expire cron 18:17:00Z succeeded", "mark": "W1 9836"}$j$::jsonb, $j${"engine_manual": "v217 (f646e032)", "op_doc": "not yet"}$j$::jsonb, $t$read back$t$, $j$[9729, 9735, 9737, 9751, 9781, 9782, 9783, 9818, 9820, 9824, 9836, "audit 38745"]$j$::jsonb, $t$W2$t$);
INSERT INTO public.ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources, owner_seat) VALUES (492, $t$2$t$, $t$debate_results direct anon INSERT closed$t$, $t$The public (anon) key can insert any row into debate_results by a direct REST POST. Close that path without breaking any live writer. Expected effect: a direct anon POST to /rest/v1/debate_results is refused with 42501; every RPC writer and every read is unchanged. (a492_w2/plan492.md)$t$, $t$in part$t$, $t$Written (audit 38761) and read back by W3 (9832), W1 (9833) and W2 (9839): the direct anon insert is refused. That every RPC writer is unchanged needs a run that saves.$t$, $t$9832, 9833, 9839$t$, 'session_01H1X3APzb2DidJoZ9Avizjn', NULL, $j$"not yet"$j$::jsonb, $j${"thread": "W4", "press_time": "18:14:12Z", "answer": "Write it", "source": "audit 38761"}$j$::jsonb, $j${"path": "a492_w2/plan492.md", "md5": "fc388155", "commit": "9f2f486a", "wall_id": 9774}$j$::jsonb, $j$[{"path": "a492_w2/step492.sql", "md5": "133ad316", "commit": "9f2f486a"}]$j$::jsonb, $j${"path": "a492_w2/revert492.sql", "md5": "928b6eca"}$j$::jsonb, $j$[{"seat": "W1", "verdict": "PASS WITH C-1", "verdict_norm": "PASS", "md5_graded": "133ad316", "wall_id": 9755}, {"seat": "W1", "verdict": "PASS", "verdict_norm": "PASS", "md5_graded": "133ad316", "wall_id": 9757}, {"seat": "W3", "verdict": "PASS", "verdict_norm": "PASS", "md5_graded": "133ad316", "wall_id": 9758}, {"seat": "W3", "verdict": "PASS ON FORM", "verdict_norm": "PASS", "md5_graded": "fc388155", "wall_id": 9775}, {"seat": "W1", "verdict": "PASS (C-1 met)", "verdict_norm": "PASS", "md5_graded": "fc388155", "wall_id": 9782}]$j$::jsonb, ARRAY['133ad316']::text[], $j$[38761]$j$::jsonb, $j$[{"kind": "policy and grant", "name": "debate_results anon_ins; INSERT for anon", "