e}$j$::jsonb, $j${"engine_manual": "v217 (f646e032)", "op_doc": "not yet"}$j$::jsonb, $t$read back$t$, $j$[9759, 9765, 9766, 9767, 9768, 9820, 9824, 9835, 9837, 9841, 9843, "audit 38773"]$j$::jsonb, $t$W2$t$);
INSERT INTO public.ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources, owner_seat) VALUES (495, $t$2$t$, $t$Oracle Hardening Test (Live Ask) unpublished$t$, $t$The workflow "TRUTH — Oracle Hardening Test (Live Ask)" (zwfk72lxBBf6ccJa) is published, and its webhook takes no credential (W1 Wall 9755). One request to that URL runs a live ask call and then a Claude drift-audit call, both paid. Expected effect: that URL no longer starts any call. Nothing the engine or the dashboard uses changes. (a495_w3/plan495.md)$t$, $t$yes$t$, $t$Written (audit 38750): the workflow is inactive, no node changed. CRITERIA (i) to (iii) read back by W2 (9822) and W1 (9823).$t$, $t$9821, 9822, 9823$t$, 'session_01H1X3APzb2DidJoZ9Avizjn', NULL, $j$"not yet"$j$::jsonb, $j${"thread": "W4", "press_time": "18:13:08Z", "answer": "Write it", "source": "audit 38750"}$j$::jsonb, $j${"path": "a495_w3/plan495.md", "md5": "dee5adcf", "commit": "5f4ea5b6", "wall_id": 9773}$j$::jsonb, $j$[]$j$::jsonb, $j${"path": "publish_workflow zwfk72lxBBf6ccJa, on the operator's word", "md5": null}$j$::jsonb, $j$[{"seat": "W1", "verdict": "PASS on form", "verdict_norm": "PASS", "md5_graded": "dee5adcf", "wall_id": 9779}, {"seat": "W2", "verdict": "PASS", "verdict_norm": "PASS", "md5_graded": "dee5adcf", "wall_id": 9784}]$j$::jsonb, ARRAY['dee5adcf']::text[], $j$[38750]$j$::jsonb, $j$[{"kind": "workflow", "name": "Oracle Hardening Test (Live Ask) zwfk72lxBBf6ccJa", "before": "active true", "after": "active false"}]$j$::jsonb, $j$"not yet"$j$::jsonb, $j$[{"seat": "W2", "result": "CONFIRMED (i) to (iii)", "wall_id": 9822}, {"seat": "W1", "result": "CONFIRMED (i) to (iii)", "wall_id": 9823}]$j$::jsonb, $j${"case": "NO PROBE (plan); the URL must not be called"}$j$::jsonb, $j${"engine_manual": "v217 (f646e032)", "op_doc": "not yet"}$j$::jsonb, $t$read back$t$, $j$[9770, 9772, 9773, 9779, 9784, 9821, 9822, 9823, "audit 38750"]$j$::jsonb, $t$W3$t$);
