 $j$[{"kind": "workflow", "name": "Debate Findings Pipeline i3bLxvLj6EL4yfak", "before": "active true", "after": "active false"}]$j$::jsonb, $j$"not yet"$j$::jsonb, $j$[{"seat": "W1", "result": "CONFIRMED", "wall_id": 9875}, {"seat": "W3", "result": "CONFIRMED", "wall_id": 9876}, {"seat": "W2", "result": "CONFIRMED (i)(ii)", "wall_id": 9878}, {"seat": "W3", "result": "(iii) none at 19:00:40Z", "wall_id": 9906}, {"seat": "W2", "result": "(iii) CONFIRMED", "wall_id": 9907}, {"seat": "W1", "result": "(iii) MET", "wall_id": 9908}]$j$::jsonb, $j${"case": "NO PROBE (plan); CRITERIA (iii)", "mark": "19:00:40Z"}$j$::jsonb, $j${"engine_manual": "v218 pending (em_pairs_v218.json cc8ffc8f)", "op_doc": "not yet"}$j$::jsonb, $t$read back$t$, $j$[9861, 9864, 9865, 9867, 9873, 9875, 9876, 9878, 9879, 9906, 9907, 9908, "audit 38810"]$j$::jsonb, $t$W2$t$);
